// Reference vectors generated by the unmodified IRremoteESP8266 C++ library.
// Build with UNIT_TEST and the five send protocols enabled; see protocol-sources.md.
#include <algorithm>
#include <cstdint>
#include <iostream>
#include <string>
#include "ir_Toshiba.h"
#include "ir_Mitsubishi.h"
#include "ir_Gree.h"
#include "ir_Kelvinator.h"
#include "ir_Electra.h"

template<typename T> void result(T &ac, const std::string &id, bool power,
    const char *mode, int temp, const char *fan, bool vertical, bool horizontal) {
  ac.send();
  uint32_t hash = 2166136261UL;
  for (int i = 0; i <= ac._irsend.last; i++) {
    uint32_t duration = ac._irsend.output[i];
    // Only Electra's final idle is bounded for TS1201's 16-bit duration format.
    if (id == "electra-104" && i == ac._irsend.last)
      duration = std::min(duration, uint32_t(65535));
    for (int j = 0; j < 4; j++) {
      hash = (hash ^ (duration & 255)) * uint32_t(16777619);
      duration >>= 8;
    }
  }
  std::cout << "{id='" << id << "',power=" << (power ? "true" : "false")
    << ",mode='" << mode << "',temperature=" << temp << ",fan='" << fan
    << "',swing_vertical='" << (vertical ? "on" : "off")
    << "',swing_horizontal='" << (horizontal ? "on" : "off")
    << "',count=" << ac._irsend.last + 1 << ",hash=" << hash << "},\n";
}

void generate(int family, int model, bool power, int mode, int temp, int fan,
    bool vertical = false, bool horizontal = false) {
  const char *modes[] = {"auto", "cool", "dry", "fan", "heat"};
  const char *fans[] = {"auto", "low", "medium", "high"};
  if (family == 0) {
    IRToshibaAC ac(0);
    int m[] = {0,1,2,4,3}, f[] = {0,1,3,5};
    ac.setModel(static_cast<toshiba_ac_remote_model_t>(model));
    ac.setMode(m[mode]); ac.setTemp(temp); ac.setFan(f[fan]);
    ac.setPower(power); ac.setSwing(vertical ? kToshibaAcSwingOn : kToshibaAcSwingOff);
    result(ac, model ? "toshiba-72-b" : "toshiba-72-a", power, modes[mode], temp, fans[fan], vertical, horizontal);
  } else if (family == 1) {
    IRMitsubishiAC ac(0);
    int m[] = {4,3,2,7,1}, f[] = {0,1,2,4};
    ac.setMode(m[mode]); ac.setTemp(temp); ac.setFan(f[fan]); ac.setPower(power);
    ac.setVane(vertical ? 7 : 1); ac.setVaneLeft(vertical ? 7 : 1);
    ac.setWideVane(horizontal ? 8 : 3);
    result(ac, "mitsubishi-144", power, modes[mode], temp, fans[fan], vertical, horizontal);
  } else if (family == 2) {
    IRGreeAC ac(0, static_cast<gree_ac_remote_model_t>(model + 1));
    ac.setMode(mode); ac.setTemp(temp); ac.setFan(fan); ac.setPower(power);
    ac.setSwingVertical(vertical, vertical ? 1 : 0); ac.setSwingHorizontal(horizontal ? 1 : 0);
    const char *ids[] = {"gree-yaw1f", "gree-ybofb", "gree-yx1fsf"};
    result(ac, ids[model], power, modes[mode], temp, fans[fan], vertical, horizontal);
  } else if (family == 3) {
    IRKelvinatorAC ac(0);
    int f[] = {0,1,3,5};
    ac.setMode(mode); ac.setTemp(temp); ac.setFan(f[fan]); ac.setPower(power);
    ac.setSwingVertical(vertical, vertical ? 1 : 0); ac.setSwingHorizontal(horizontal);
    result(ac, "kelvinator-128", power, modes[mode], temp, fans[fan], vertical, horizontal);
  } else {
    IRElectraAc ac(0);
    int m[] = {0,1,2,6,4}, f[] = {5,3,2,1};
    ac.setMode(m[mode]); ac.setTemp(temp); ac.setFan(f[fan]); ac.setPower(power);
    ac.setSwingV(vertical); ac.setSwingH(horizontal);
    result(ac, "electra-104", power, modes[mode], temp, fans[fan], vertical, horizontal);
  }
}

int main() {
  std::cout << "-- Generated by tests/reference/generate_ac_fixtures.cpp against IRremoteESP8266.\nreturn {\n";
  for (int family = 0; family < 5; family++) {
    int models = family == 0 ? 2 : family == 2 ? 3 : 1;
    for (int model = 0; model < models; model++) {
      for (int power = 0; power < 2; power++)
        for (int mode = 0; mode < 5; mode++)
          for (int fan = 0; fan < 4; fan++) {
            if (family == 2 && mode == 2 && fan != 1) continue;
            int temp = ((family == 2 && mode == 0) ||
              (family == 3 && (mode == 0 || mode == 2))) ? 25 : 24;
            generate(family, model, power, mode, temp, fan);
          }
      for (int temp : {family == 0 ? 17 : 16, family == 1 ? 31 : family == 4 ? 32 : 30})
        generate(family, model, true, 1, temp, 3);
      generate(family, model, true, 1, 24, 2, true, false);
      if (family != 0) {
        generate(family, model, true, 1, 24, 2, false, true);
        generate(family, model, true, 1, 24, 2, true, true);
      }
    }
  }
  std::cout << "}\n";
}
